/// View over multiple CoreSourcesSource with field accumulation
pub struct CoreSourcesSourceSliceView<'a, D> {
    pub identifier: CoreSourcesSourceIdentifierView<'a, D>,
    pub species: CoreSourcesSourceSpeciesView<'a, D>,
    pub code: CoreSourcesSourceCodeView<'a, D>,
    slice_elements: Elements<'a, CoreSourcesSource, D>,
}

impl<'a, D: Dimension> CoreSourcesSourceSliceView<'a, D> {
    pub fn new(elements: Elements<'a, CoreSourcesSource, D>) -> Self {
        Self {
            identifier: CoreSourcesSourceIdentifierView::new(elements.clone()),
            species: CoreSourcesSourceSpeciesView::new(elements.clone()),
            code: CoreSourcesSourceCodeView::new(elements.clone()),
            slice_elements: elements,
        }
    }

    /// Total number of elements, across every sliced level
    pub fn len(&self) -> usize {
        self.slice_elements.len()
    }

    pub fn is_empty(&self) -> bool {
        self.slice_elements.is_empty()
    }

    /// The length of each sliced level, in path order like the gathered arrays
    pub fn shape(&self) -> Vec<usize> {
        self.slice_elements.shape()
    }

    /// Every element, in path order: the first array of structures on the path varies slowest
    pub fn iter(&self) -> impl Iterator<Item = &'a CoreSourcesSource> + '_ {
        self.slice_elements.iter()
    }

    /// Select from `global_quantities` under every element. A range, e.g. `.global_quantities(..)`, adds one dimension,
    /// after those of the levels sliced above it and before the leaf's own.
    ///
    /// # Panics
    /// If a range does not select the same number of elements under every element.
    pub fn global_quantities<S: Selection<'a, CoreSourcesSourceGlobal>>(&self, selection: S) -> S::NestedOutput<D> {
        selection.select_nested("global_quantities", &self.slice_elements, |item: &CoreSourcesSource| {
            item.global_quantities.as_slice()
        })
    }

    /// Select from `profiles_1d` under every element. A range, e.g. `.profiles_1d(..)`, adds one dimension,
    /// after those of the levels sliced above it and before the leaf's own.
    ///
    /// # Panics
    /// If a range does not select the same number of elements under every element.
    pub fn profiles_1d<S: Selection<'a, CoreSourcesSourceProfiles1d>>(&self, selection: S) -> S::NestedOutput<D> {
        selection.select_nested("profiles_1d", &self.slice_elements, |item: &CoreSourcesSource| item.profiles_1d.as_slice())
    }
}

impl ArrayOfStructuresElement for CoreSourcesSource {
    type SliceView<'a, D>
        = CoreSourcesSourceSliceView<'a, D>
    where
        Self: 'a;

    fn slice_view<'a, D: Dimension>(elements: Elements<'a, Self, D>) -> Self::SliceView<'a, D>
    where
        Self: 'a,
    {
        CoreSourcesSourceSliceView::new(elements)
    }
}

